final class AccessService {
    private static function isSystemAdmin(Actor $a):bool{return HierarchyScope::hasCompanyWideSystemAuthority($a);}
    private static function isReservedSystemRoleCode(string $code):bool{return in_array(strtoupper(trim($code)),['SYSTEM_ADMIN','SYSADMIN','ADMIN','ADMINISTRATOR'],true);}
    private static function assertCanMutateRoleIds(Actor $a,array $roleIds):void{if(self::isSystemAdmin($a)||!$roleIds)return;$ids=array_values(array_unique(array_filter(array_map('intval',$roleIds))));if(!$ids)return;$place=implode(',',array_fill(0,count($ids),'%d'));$db=Db::wpdb();$count=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('roles')." WHERE company_id=%d AND id IN ({$place}) AND UPPER(code) IN ('SYSTEM_ADMIN','SYSADMIN','ADMIN','ADMINISTRATOR')",$a->companyId,...$ids));if($count)throw new DomainException('Reserved system roles require company-wide system authority.','reserved_system_role_forbidden',403);}
    public static function assertCanDelegateCapabilities(Actor $a,array $caps):void{if(self::isSystemAdmin($a))return;$missing=array_values(array_diff(array_unique(array_map('strval',$caps)),$a->capabilities));if($missing)throw new DomainException('Cannot grant, revoke or reshape authority you do not hold.','authority_escalation_forbidden',403);}
    private static function assertRoleWithinAuthority(Actor $a,int $roleId):void{if(self::isSystemAdmin($a))return;$db=Db::wpdb();$assigned=array_map('intval',(array)$db->get_col($db->prepare("SELECT er.employee_id FROM ".Db::table('employee_roles')." er JOIN ".Db::table('employees')." e ON e.id=er.employee_id AND e.company_id=er.company_id WHERE er.company_id=%d AND er.role_id=%d AND er.active=1",$a->companyId,$roleId)));$manageable=array_flip(HierarchyScope::manageableEmployeeIds($a));foreach($assigned as$employeeId)if(!isset($manageable[$employeeId]))throw new DomainException('Role is assigned outside delegated reporting authority.','role_scope_forbidden',403);}
    public static function assertCanAdministerEmployeeIdentity(Actor $a,int $employeeId):void{HierarchyScope::assertCanManageEmployeeAccess($a,$employeeId);if(self::isSystemAdmin($a))return;$db=Db::wpdb();$activeRoleIds=array_map('intval',(array)$db->get_col($db->prepare("SELECT role_id FROM ".Db::table('employee_roles')." WHERE company_id=%d AND employee_id=%d AND active=1",$a->companyId,$employeeId)));self::assertCanMutateRoleIds($a,$activeRoleIds);$e=$db->get_row($db->prepare("SELECT designation_code FROM ".Db::table('employees')." WHERE company_id=%d AND id=%d",$a->companyId,$employeeId),ARRAY_A);if(!$e)throw new DomainException('Employee not found.','employee_not_found',404);self::assertCanDelegateCapabilities($a,self::effectiveCapabilities($a->companyId,$employeeId,(string)$e['designation_code']));}
    
    public static function employeeChoices(Actor $a,?int $branch=null):array {
        Guard::cap($a,Capabilities::ACCESS_MANAGE);
        $ids=HierarchyScope::manageableEmployeeIds($a);
        return \ExcelHerbal\ERP7\Organization\EmployeeChoiceService::list($a,$branch,false,true,$ids);
    }
    private static function isReservedRole(string $code):bool{return in_array(strtoupper(trim($code)),['SYSADMIN','SYSTEM_ADMIN','ADMIN','ADMINISTRATOR'],true);}
    /** @return string[] */ private static function knownCapabilities():array{return array_values(array_unique(array_values((new \ReflectionClass(Capabilities::class))->getConstants())));}
    public static function matrix(Actor $a):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);$db=Db::wpdb();$roles=(array)$db->get_results($db->prepare("SELECT id,code,name,active FROM ".Db::table('roles')." WHERE company_id=%d ORDER BY name",$a->companyId),ARRAY_A);foreach($roles as&$r){$r['capabilities']=(array)$db->get_col($db->prepare("SELECT capability FROM ".Db::table('role_capabilities')." WHERE role_id=%d AND active=1 ORDER BY capability",(int)$r['id']));}unset($r);return['capabilities'=>self::knownCapabilities(),'roles'=>$roles,'designation_defaults'=>DesignationDefaults::profiles()];}
    public static function createRole(Actor $a,string $code,string $name):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);$code=strtoupper(trim($code));$name=trim($name);if($code===''||$name==='')throw new DomainException('Role code and name are required.','role_fields_required',422);if(self::isReservedRole($code))throw new DomainException('System role codes are reserved.','reserved_system_role_forbidden',403);$db=Db::wpdb();Db::mustInsert($db,Db::table('roles'),['company_id'=>$a->companyId,'code'=>$code,'name'=>$name,'active'=>1],'Role code already exists.','role_duplicate');$id=(int)$db->insert_id;Audit::add($a,'access.role_create','role',$id,['code'=>$code]);return['id'=>$id,'code'=>$code,'name'=>$name,'active'=>true];}
    public static function setRoleCapabilities(Actor $a,int $roleId,array $caps,string $reason):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);if(strlen(trim($reason))<5)throw new DomainException('Access-change reason is required.','access_reason_required',422);$known=self::knownCapabilities();$wanted=array_values(array_unique(array_map('strval',$caps)));if(array_diff($wanted,$known))throw new DomainException('Unknown capability supplied.','capability_invalid',422);self::assertCanDelegateCapabilities($a,$wanted);return Transaction::run(function()use($a,$roleId,$wanted,$reason,$known){$db=Db::wpdb();$role=$db->get_row($db->prepare("SELECT * FROM ".Db::table('roles')." WHERE id=%d AND company_id=%d AND active=1 FOR UPDATE",$roleId,$a->companyId),ARRAY_A);if(!$role)throw new DomainException('Active role not found.','role_not_found',404);if(self::isReservedRole((string)$role['code']))throw new DomainException('System role capabilities are not editable here.','reserved_system_role_forbidden',403);$selfAssigned=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('employee_roles')." WHERE company_id=%d AND employee_id=%d AND role_id=%d AND active=1",$a->companyId,$a->employeeId,$roleId));if($selfAssigned&&(!in_array(Capabilities::ACCESS,$wanted,true)||!in_array(Capabilities::ACCESS_MANAGE,$wanted,true)))throw new DomainException('Cannot remove own ERP/access-management capability through an assigned role.','self_access_lockout',409);$t=Db::table('role_capabilities');$before=(array)$db->get_col($db->prepare("SELECT capability FROM {$t} WHERE role_id=%d AND active=1 ORDER BY capability",$roleId));self::assertRoleWithinAuthority($a,$roleId);self::assertCanDelegateCapabilities($a,array_merge($before,$wanted));$rows=(array)$db->get_results($db->prepare("SELECT id,capability,active FROM {$t} WHERE role_id=%d",$roleId),ARRAY_A);$by=[];foreach($rows as$r)$by[(string)$r['capability']]=$r;foreach($known as$cap){$active=in_array($cap,$wanted,true)?1:0;if(isset($by[$cap]))Db::mustUpdate($db,$t,['active'=>$active,'updated_at'=>Db::now()],['id'=>(int)$by[$cap]['id']]);elseif($active)Db::mustInsert($db,$t,['role_id'=>$roleId,'capability'=>$cap,'active'=>1,'created_at'=>Db::now()]);}Audit::add($a,'access.role_capabilities','role',$roleId,['before'=>$before,'after'=>$wanted,'reason'=>trim($reason)]);return['role_id'=>$roleId,'capabilities'=>$wanted];});}
    public static function employeeAccess(Actor $a,int $employeeId):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);$db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT id,full_name,designation_code,assigned_branch_id,status FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d",$employeeId,$a->companyId),ARRAY_A);if(!$e)throw new DomainException('Employee not found.','employee_not_found',404);if(!$a->hasBranch((int)$e['assigned_branch_id']))throw new DomainException('Employee branch is outside effective authority.','branch_forbidden',403);self::assertCanAdministerEmployeeIdentity($a,$employeeId);$roles=(array)$db->get_results($db->prepare("SELECT r.id,r.code,r.name FROM ".Db::table('employee_roles')." er JOIN ".Db::table('roles')." r ON r.id=er.role_id AND r.active=1 WHERE er.company_id=%d AND er.employee_id=%d AND er.active=1 ORDER BY r.name",$a->companyId,$employeeId),ARRAY_A);return['employee'=>$e,'roles'=>$roles,'branch_ids'=>BranchAuthority::ids($employeeId,$a->companyId),'designation_defaults'=>DesignationDefaults::forCode((string)($e['designation_code']??'')),'overrides'=>self::employeeOverrides($a->companyId,$employeeId),'effective_capabilities'=>self::effectiveCapabilities($a->companyId,$employeeId,(string)($e['designation_code']??''))];}
    public static function setEmployeeRoles(Actor $a,int $employeeId,array $roleIds,string $reason):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);if(strlen(trim($reason))<5)throw new DomainException('Access-change reason is required.','access_reason_required',422);$wanted=array_values(array_unique(array_filter(array_map('intval',$roleIds))));return Transaction::run(function()use($a,$employeeId,$wanted,$reason){$db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT id,designation_code,assigned_branch_id FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d AND status='active' FOR UPDATE",$employeeId,$a->companyId),ARRAY_A);if(!$e)throw new DomainException('Active employee not found.','employee_not_found',404);if(!$a->hasBranch((int)$e['assigned_branch_id']))throw new DomainException('Employee branch is outside effective authority.','branch_forbidden',403);HierarchyScope::assertCanManageEmployeeAccess($a,$employeeId);$place=$wanted?implode(',',array_fill(0,count($wanted),'%d')):'';$args=array_merge([$a->companyId],$wanted);$valid=$wanted?array_map('intval',(array)$db->get_col($db->prepare("SELECT id FROM ".Db::table('roles')." WHERE company_id=%d AND active=1 AND id IN ({$place})",...$args))):[];sort($valid);$sorted=$wanted;sort($sorted);if($valid!==$sorted)throw new DomainException('One or more roles are invalid.','role_invalid',422);$currentRoleIds=array_map('intval',(array)$db->get_col($db->prepare("SELECT role_id FROM ".Db::table('employee_roles')." WHERE company_id=%d AND employee_id=%d AND active=1",$a->companyId,$employeeId)));$affectedRoleIds=array_values(array_unique(array_merge($currentRoleIds,$wanted)));self::assertCanMutateRoleIds($a,$affectedRoleIds);$affectedCaps=[];if($affectedRoleIds){$affectedPlace=implode(',',array_fill(0,count($affectedRoleIds),'%d'));$affectedCaps=(array)$db->get_col($db->prepare("SELECT DISTINCT capability FROM ".Db::table('role_capabilities')." WHERE active=1 AND role_id IN ({$affectedPlace})",...$affectedRoleIds));}self::assertCanDelegateCapabilities($a,$affectedCaps);if($wanted){$selectedCaps=(array)$db->get_col($db->prepare("SELECT DISTINCT capability FROM ".Db::table('role_capabilities')." WHERE active=1 AND role_id IN ({$place})",...$wanted));if(array_diff($selectedCaps,$a->capabilities))throw new DomainException('Cannot assign a role with capabilities outside your own authority.','capability_escalation_forbidden',403);}if($wanted){$reserved=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('roles')." WHERE company_id=%d AND id IN ({$place}) AND UPPER(code) IN ('SYSADMIN','SYSTEM_ADMIN','ADMIN','ADMINISTRATOR')",...$args));if($reserved)throw new DomainException('System roles may not be manually assigned.','reserved_system_role_forbidden',403);}if($employeeId===$a->employeeId){$caps=DesignationDefaults::forCode((string)$e['designation_code']);if($wanted){$roleCaps=(array)$db->get_col($db->prepare("SELECT DISTINCT capability FROM ".Db::table('role_capabilities')." WHERE active=1 AND role_id IN ({$place})",...$wanted));$caps=array_merge($caps,$roleCaps);}foreach(self::employeeOverrides($a->companyId,$employeeId) as$ov){$cap=(string)$ov['capability'];if($ov['effect']==='grant')$caps[]=$cap;elseif($ov['effect']==='deny')$caps=array_values(array_diff($caps,[$cap]));}$caps=array_values(array_unique($caps));if(!in_array(Capabilities::ACCESS,$caps,true)||!in_array(Capabilities::ACCESS_MANAGE,$caps,true))throw new DomainException('Cannot remove own ERP/access-management capability.','self_access_lockout',409);} $t=Db::table('employee_roles');$before=array_map('intval',(array)$db->get_col($db->prepare("SELECT role_id FROM {$t} WHERE company_id=%d AND employee_id=%d AND active=1 ORDER BY role_id",$a->companyId,$employeeId)));$rows=(array)$db->get_results($db->prepare("SELECT id,role_id FROM {$t} WHERE company_id=%d AND employee_id=%d",$a->companyId,$employeeId),ARRAY_A);$by=[];foreach($rows as$r)$by[(int)$r['role_id']]=$r;foreach($by as$rid=>$r)if(!in_array($rid,$wanted,true))Db::mustUpdate($db,$t,['active'=>0,'revoked_at'=>Db::now()],['id'=>(int)$r['id']]);foreach($wanted as$rid){if(isset($by[$rid]))Db::mustUpdate($db,$t,['active'=>1,'assigned_by'=>$a->employeeId,'assigned_at'=>Db::now(),'revoked_at'=>null],['id'=>(int)$by[$rid]['id']]);elseDb::mustInsert($db,$t,['company_id'=>$a->companyId,'employee_id'=>$employeeId,'role_id'=>$rid,'active'=>1,'assigned_by'=>$a->employeeId,'assigned_at'=>Db::now()]);}Audit::add($a,'access.employee_roles','employee',$employeeId,['before'=>$before,'after'=>$wanted,'reason'=>trim($reason),'branch_id'=>(int)$e['assigned_branch_id']]);return['employee_id'=>$employeeId,'role_ids'=>$wanted];});}
    private static function employeeOverrides(int $companyId,int $employeeId):array{$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT capability,effect FROM ".Db::table('employee_capability_overrides')." WHERE company_id=%d AND employee_id=%d AND active=1 ORDER BY capability",$companyId,$employeeId),ARRAY_A);}
    private static function effectiveCapabilities(int $companyId,int $employeeId,string $designation):array{$db=Db::wpdb();$caps=DesignationDefaults::forCode($designation);$role=(array)$db->get_col($db->prepare("SELECT DISTINCT rc.capability FROM ".Db::table('employee_roles')." er JOIN ".Db::table('role_capabilities')." rc ON rc.role_id=er.role_id AND rc.active=1 JOIN ".Db::table('roles')." r ON r.id=er.role_id AND r.active=1 WHERE er.company_id=%d AND er.employee_id=%d AND er.active=1",$companyId,$employeeId));$caps=array_values(array_unique(array_merge($caps,array_map('strval',$role))));foreach(self::employeeOverrides($companyId,$employeeId) as$r){$cap=(string)$r['capability'];if($r['effect']==='grant')$caps[]=$cap;elseif($r['effect']==='deny')$caps=array_values(array_diff($caps,[$cap]));}return array_values(array_unique($caps));}
    public static function setEmployeeOverrides(Actor $a,int $employeeId,array $grants,array $denies,string $reason):array{Guard::cap($a,Capabilities::ACCESS_MANAGE);if(strlen(trim($reason))<5)throw new DomainException('Access-change reason is required.','access_reason_required',422);$known=self::knownCapabilities();$grants=array_values(array_unique(array_map('strval',$grants)));$denies=array_values(array_unique(array_map('strval',$denies)));if(array_diff(array_merge($grants,$denies),$known))throw new DomainException('Unknown capability supplied.','capability_invalid',422);self::assertCanDelegateCapabilities($a,array_merge($grants,$denies));if(array_intersect($grants,$denies))throw new DomainException('A capability cannot be both granted and denied.','capability_override_conflict',422);return Transaction::run(function()use($a,$employeeId,$grants,$denies,$reason){$db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT id,designation_code,assigned_branch_id FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d AND status='active' FOR UPDATE",$employeeId,$a->companyId),ARRAY_A);if(!$e)throw new DomainException('Active employee not found.','employee_not_found',404);if(!$a->hasBranch((int)$e['assigned_branch_id']))throw new DomainException('Employee branch is outside effective authority.','branch_forbidden',403);HierarchyScope::assertCanManageEmployeeAccess($a,$employeeId);if($employeeId===$a->employeeId&&in_array(Capabilities::ACCESS_MANAGE,$denies,true))throw new DomainException('Cannot deny your own access-management capability.','self_access_lockout',409);$t=Db::table('employee_capability_overrides');$before=self::employeeOverrides($a->companyId,$employeeId);self::assertCanDelegateCapabilities($a,array_merge(array_column($before,'capability'),$grants,$denies));$wanted=[];foreach($grants as$cap)$wanted[$cap]='grant';foreach($denies as$cap)$wanted[$cap]='deny';$rows=(array)$db->get_results($db->prepare("SELECT id,capability FROM {$t} WHERE company_id=%d AND employee_id=%d",$a->companyId,$employeeId),ARRAY_A);$by=[];foreach($rows as$r)$by[(string)$r['capability']]=$r;foreach($by as$cap=>$r){if(!isset($wanted[$cap]))Db::mustUpdate($db,$t,['active'=>0],['id'=>(int)$r['id']]);}foreach($wanted as$cap=>$effect){$data=['effect'=>$effect,'active'=>1,'created_by'=>$a->employeeId,'created_at'=>Db::now()];if(isset($by[$cap]))Db::mustUpdate($db,$t,$data,['id'=>(int)$by[$cap]['id']]);elseDb::mustInsert($db,$t,['company_id'=>$a->companyId,'employee_id'=>$employeeId,'capability'=>$cap]+$data);}Audit::add($a,'access.employee_overrides','employee',$employeeId,['before'=>$before,'grants'=>$grants,'denies'=>$denies,'reason'=>trim($reason)]);return['employee_id'=>$employeeId,'grants'=>$grants,'denies'=>$denies,'effective_capabilities'=>self::effectiveCapabilities($a->companyId,$employeeId,(string)$e['designation_code'])];});}

